<?php
require 'helpers.php'; requerirLogin();
if(!puede('ver_dashboard')){http_response_code(403);exit('Sin permiso.');}
$clienteId=(int)usuario()['cliente_id'];$error='';$ok='';$st=db()->prepare('SELECT id,nombre,moneda FROM costobene_productos WHERE cliente_id=? ORDER BY nombre');$st->execute([$clienteId]);$productos=$st->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){try{validarCsrf('csrf_produccion');$accion=(string)($_POST['accion']??'');
 if($accion==='crear'){if(!puede('cargar_produccion'))throw new RuntimeException('No tenés permiso para cargar producción.');$pid=(int)($_POST['producto_id']??0);$anio=filter_var($_POST['anio']??null,FILTER_VALIDATE_INT);$mes=filter_var($_POST['mes']??null,FILTER_VALIDATE_INT);$campos=['unidades_vendidas','precio_promedio_real','costos_fijos_reales','costos_variables_reales','costos_indirectos_reales','mano_obra_real'];$v=[];foreach($campos as $c){$n=filter_var($_POST[$c]??0,FILTER_VALIDATE_FLOAT);if($n===false||$n<0)throw new RuntimeException('Los valores operativos deben ser números iguales o mayores a cero.');$v[]=$n;}if($anio<2000||$anio>2100||$mes<1||$mes>12)throw new RuntimeException('Indicá un período válido.');$chk=db()->prepare('SELECT id FROM costobene_productos WHERE id=? AND cliente_id=?');$chk->execute([$pid,$clienteId]);if(!$chk->fetch())throw new RuntimeException('Seleccioná un producto o servicio de tu empresa.');$estado=esOperador()?'pendiente':'aprobado';$ins=db()->prepare('INSERT INTO costobene_produccion_mensual_producto (producto_id,creado_por,anio,mes,unidades_vendidas,precio_promedio_real,costos_fijos_reales,costos_variables_reales,costos_indirectos_reales,mano_obra_real,estado_aprobacion) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$ins->execute(array_merge([$pid,(int)usuario()['id'],$anio,$mes],$v,[$estado]));$ok='Datos de producción cargados.';
 }elseif(in_array($accion,['aprobar','rechazar'],true)){if(!puede('aprobar_cargas'))throw new RuntimeException('No tenés permiso para revisar cargas.');$id=(int)($_POST['id']??0);$estado=$accion==='aprobar'?'aprobado':'rechazado';$up=db()->prepare('UPDATE costobene_produccion_mensual_producto pm JOIN costobene_productos p ON p.id=pm.producto_id SET pm.estado_aprobacion=?,pm.aprobado_por=?,pm.aprobado_en=NOW() WHERE pm.id=? AND p.cliente_id=? AND pm.estado_aprobacion=\'pendiente\'');$up->execute([$estado,(int)usuario()['id'],$id,$clienteId]);$ok='Revisión de producción guardada.';
 }elseif($accion==='editar'){ $id=(int)($_POST['id']??0);$fields=['unidades_vendidas','precio_promedio_real','costos_fijos_reales','costos_variables_reales','costos_indirectos_reales','mano_obra_real'];$vals=[];foreach($fields as $field){$n=filter_var($_POST[$field]??null,FILTER_VALIDATE_FLOAT);if($n===false||$n<0)throw new RuntimeException('Todos los valores operativos deben ser mayores o iguales a cero.');$vals[]=$n;}if(!esOperador()||!puede('editar_cargas_propias'))throw new RuntimeException('No se puede editar esta carga.');$up=db()->prepare('UPDATE costobene_produccion_mensual_producto pm JOIN costobene_productos p ON p.id=pm.producto_id SET pm.unidades_vendidas=?,pm.precio_promedio_real=?,pm.costos_fijos_reales=?,pm.costos_variables_reales=?,pm.costos_indirectos_reales=?,pm.mano_obra_real=? WHERE pm.id=? AND p.cliente_id=? AND pm.creado_por=? AND pm.estado_aprobacion=\'pendiente\'');$up->execute(array_merge($vals,[$id,$clienteId,(int)usuario()['id']]));$ok='Carga pendiente actualizada.';}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la carga. Verificá la migración SQL.';}}
$q=db()->prepare('SELECT pm.*,p.nombre producto FROM costobene_produccion_mensual_producto pm JOIN costobene_productos p ON p.id=pm.producto_id WHERE p.cliente_id=? ORDER BY pm.anio DESC,pm.mes DESC,pm.id DESC');$q->execute([$clienteId]);$registros=$q->fetchAll();$csrf=csrfToken('csrf_produccion');$paginaActual='produccion';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Producción - CostoPyme</title><link rel="stylesheet" href="style.css"></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main"><header class="page-head"><div><h1>Producción</h1><p>Registrá datos operativos mensuales y revisá las cargas pendientes.</p></div></header><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if($ok):?><div class="success"><?=h($ok)?></div><?php endif;?>
<?php if(puede('cargar_produccion')):?><section class="panel"><h2>Cargar datos operativos</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="crear"><div class="form-grid"><label>Producto o servicio *<select name="producto_id" required><?php foreach($productos as $pr):?><option value="<?=(int)$pr['id']?>"><?=h($pr['nombre'])?></option><?php endforeach;?></select></label><label>Año *<input type="number" name="anio" min="2000" max="2100" value="<?=date('Y')?>" required></label><label>Mes *<select name="mes"><?php for($i=1;$i<=12;$i++):?><option value="<?=$i?>" <?=$i===(int)date('n')?'selected':''?>><?=$i?></option><?php endfor;?></select></label><label>Unidades vendidas *<input type="number" name="unidades_vendidas" min="0" step="0.01" value="0"></label><label>Precio promedio real *<input type="number" name="precio_promedio_real" min="0" step="0.01" value="0"></label><label>Costos fijos reales *<input type="number" name="costos_fijos_reales" min="0" step="0.01" value="0"></label><label>Costos variables reales *<input type="number" name="costos_variables_reales" min="0" step="0.01" value="0"></label><label>Costos indirectos reales *<input type="number" name="costos_indirectos_reales" min="0" step="0.01" value="0"></label><label>Mano de obra real *<input type="number" name="mano_obra_real" min="0" step="0.01" value="0"></label></div><div class="actions"><button type="submit">Guardar datos operativos</button></div><?php if(esOperador()):?><p class="help">Tus cargas quedan pendientes hasta que el encargado las apruebe. Podés editar unidades y precio mientras estén pendientes.</p><?php endif;?></form></section><?php endif;?>
<section class="panel"><h2>Historial de producción</h2><?php if(!$registros):?><div class="empty">Todavía no hay registros.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Período</th><th>Unidades</th><th>Precio promedio</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?=h($r['producto'])?></td><td><?=sprintf('%02d/%d',(int)$r['mes'],(int)$r['anio'])?></td><td><?=number_format((float)$r['unidades_vendidas'],2,',','.')?></td><td><?=number_format((float)$r['precio_promedio_real'],2,',','.')?></td><td><?=h($r['estado_aprobacion'])?></td><td><?php if(puede('aprobar_cargas')&&$r['estado_aprobacion']==='pendiente'):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="accion" value="aprobar">Aprobar</button><button class="btn-secondary" name="accion" value="rechazar">Rechazar</button></form><?php elseif(esOperador()&&(int)$r['creado_por']===(int)usuario()['id']&&$r['estado_aprobacion']==='pendiente'):?><details><summary>Editar carga</summary><form method="post" class="inline-edit"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="editar"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><?php foreach(['unidades_vendidas'=>'Unidades','precio_promedio_real'=>'Precio promedio','costos_fijos_reales'=>'Costos fijos','costos_variables_reales'=>'Costos variables','costos_indirectos_reales'=>'Costos indirectos','mano_obra_real'=>'Mano de obra'] as $field=>$caption):?><label><?=h($caption)?><input type="number" name="<?=h($field)?>" min="0" step="0.01" value="<?=h($r[$field])?>"></label><?php endforeach;?><button class="btn-secondary">Guardar cambios</button></form></details><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
</main></div></body></html>
